contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        // baseline: read owner before any state-changing call
        address beforeOwner = c.owner();

        // attempt a state-changing call from a non-admin caller (this test contract is not the admin,
        // since c was deployed by an external deployer, so msg.sender (this contract) != admin)
        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: for a non-admin caller, the call must revert and leave owner unchanged.
        assert(reverted && c.owner() == beforeOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address adminBefore = c.admin();
        address ownerBefore = c.owner();

        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The admin is immutable; a successful setOwner changes only the owner.
        assert(c.admin() == adminBefore && (reverted ? c.owner() == ownerBefore : c.owner() == newOwner));
    }

    receive() external payable {}
}

